'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createRealmGate']);
const { createRealmGate } = api;

assert.throws(() => createRealmGate(null, []), TypeError);
assert.throws(() => createRealmGate({}, null), TypeError);
for (const resource of [null, 1, 'x', {}, { id: '', realmId: 'r' }, { id: 'x', realmId: '' }, { id: 1, realmId: 'r' }, { id: 'x', realmId: 1 }]) {
  assert.throws(() => createRealmGate({}, [resource]), TypeError);
}

const memberships = { alice: 'red', bob: 'blue', invalid: 3, empty: '' };
const resources = [
  { id: 'shared', realmId: 'blue', extra: true },
  { id: 'red-only', realmId: 'red' },
  { id: 'shared', realmId: 'red' }
];
const gate = createRealmGate(memberships, resources);
assert.strictEqual(gate.realmFor('alice'), 'red');
assert.strictEqual(gate.realmFor('bob'), 'blue');
assert.strictEqual(gate.realmFor('empty'), '');
assert.strictEqual(gate.realmFor('invalid'), null);
assert.strictEqual(gate.realmFor('unknown'), null);
assert.strictEqual(gate.realmFor(1), null);
assert.strictEqual(gate.canAccess('alice', 'red-only'), true);
assert.strictEqual(gate.canAccess('bob', 'red-only'), false);
assert.strictEqual(gate.canAccess('alice', 'shared'), true);
assert.strictEqual(gate.canAccess('bob', 'shared'), true);
assert.strictEqual(gate.canAccess('unknown', 'shared'), false);
assert.strictEqual(gate.canAccess('alice', ''), false);
assert.strictEqual(gate.canAccess('alice', null), false);
assert.strictEqual(gate.canAccess(null, 'shared'), false);

memberships.alice = 'blue';
resources[1].realmId = 'blue';
resources.push({ id: 'late', realmId: 'red' });
assert.strictEqual(gate.realmFor('alice'), 'red');
assert.strictEqual(gate.canAccess('alice', 'red-only'), true);
assert.strictEqual(gate.canAccess('alice', 'late'), false);

